struct SecureGroup: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let user = request.auth.get(User.self) else { throw Abort(.unauthorized) }
        try await Audit.record(user, request.url.path)
        return try await next.respond(to: request)
    }
}

let protected = app.grouped(UserAuthenticator(), User.guardMiddleware(), SecureGroup())
